def fill_referral_codes(apps, schema_editor):
    """Give every customer a referral code."""
    User = apps.get_model("accounts", "User")

    used = set()
    for account in User.objects.all().iterator():
        base = "REF" + secrets.token_hex(4).upper()
        code = base
        number = 2
        while code in used:
            code = f"{base}{number}"
            number += 1
        used.add(code)
        account.referral_code = code
        account.save(update_fields=["referral_code"])


